function buildKnowledgeIndex(app, enabled, maxFiles = 0) {
  if (!enabled)
    return "";
  const mdFiles = app.vault.getMarkdownFiles();
  if (mdFiles.length === 0)
    return "";
  let lines = mdFiles.map((f) => `- ${f.path}`).sort();
  if (maxFiles > 0 && lines.length > maxFiles) {
    lines = lines.slice(lines.length - maxFiles);
    lines.push(
      `... (${mdFiles.length - lines.length} more files omitted, total ${mdFiles.length})`
    );
  }
  return [
    "# Knowledge base index (paths only \u2014 file contents are NOT loaded unless explicitly attached or referenced)",
    ...lines
  ].join("\n");
}
